import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
import {resolve} from 'node:path';
const load = name => import(pathToFileURL(resolve(name)).href);
const typecheck="import {createPerson,type Person} from './src/person.ts'; const p:Person=createPerson('Ada',36);\n// @ts-expect-error wrong argument types\ncreatePerson(4,'bad');\n// @ts-expect-error name is a string\nconst bad:Person={name:5,age:3};\n";
import {spawnSync} from 'node:child_process';
import {writeFileSync,unlinkSync} from 'node:fs';
const checkPath='.ur-eval-typecheck.ts';
try {writeFileSync(checkPath,typecheck); const result=spawnSync('npx',['--yes','--package','typescript@5.9.3','tsc','--noEmit','--strict','--skipLibCheck','--target','ES2022','--module','NodeNext','--moduleResolution','NodeNext','--allowImportingTsExtensions',checkPath],{encoding:'utf8',timeout:120000}); assert.equal(result.status,0,result.stdout+result.stderr); } finally {try{unlinkSync(checkPath)}catch{}}
const {createPerson}=await load('src/person.ts'); assert.deepEqual(createPerson('Ada',36),{name:'Ada',age:36});
import {existsSync} from 'node:fs'; assert.equal(existsSync('src/person.js'),false);

